{
  "title": "The Mirror Bridge Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a ruined map at the edge of the city.",
      "visual_description": "Mara the Cartographer crouches under a broken arch, unrolling a faded parchment while the setting sun casts long shadows through rubble.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver checks his helmet before entering a mirror.",
      "visual_description": "The Glass Diver adjusts his clear diving helmet near a shattered mirror leaning against a cracked wall, his coat reflecting the orange sky.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning about the castle gates.",
      "visual_description": "The Oracle Lamp sits on a stone, its single eye in the flame darting toward the distant, rusted castle gates while smoke rises.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The Tin Fox scampers ahead to scout the entrance.",
      "visual_description": "The Tin Fox darts over fallen stones, its key-wind tail spinning, blue eyes scanning the path to the castle gates.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The Sleeping Tax Collector naps near the gatehouse.",
      "visual_description": "The Sleeping Tax Collector snores on a pile of stamped papers, using a ledger book as a pillow, oblivious to the broken gate behind him.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara navigates through a maze of collapsed towers.",
      "visual_description": "Mara steps carefully between leaning tower fragments, compass in hand, as dust motes float in slanting light.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The Glass Diver peers through a window into a cursed tower.",
      "visual_description": "The Glass Diver presses his helmet against a grimy window, seeing a spiral staircase inside that glows faintly green.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The Oracle Lamp warns of a trap in the tower's shadow.",
      "visual_description": "The Oracle Lamp hovers near the tower base, its flame shrinking as it whispers, casting dancing shadows on the stones.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The Tin Fox discovers a hidden passage under the tower.",
      "visual_description": "The Tin Fox sniffs at a loose flagstone, its metal tail clicking as it reveals a dark hole with stone steps.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Mara marks the secret route on her map.",
      "visual_description": "Mara kneels by the passage, inking a new line onto her parchment while the Tin Fox waits at her feet.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The Sleeping Tax Collector stirs but does not wake.",
      "visual_description": "The Sleeping Tax Collector shifts, muttering numbers, as a stamped paper flutters from his sleeve into the wind.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "The Glass Diver swims through a magic door's reflection.",
      "visual_description": "The Glass Diver steps into a tall bronze mirror, his image rippling as he enters a corridor of light beyond the door.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The Oracle Lamp warns of armored patrols ahead.",
      "visual_description": "The Oracle Lamp glows red, its eye fixed on a distant street where clockwork figures march in unison.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "Mara leads the group through a crumbling marketplace.",
      "visual_description": "Mara hurries past collapsed stalls and torn banners, holding her compass low, the Tin Fox beside her.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The Glass Diver retrieves a key from a mirror pool.",
      "visual_description": "The Glass Diver kneels at a rain-filled basin, plunging his hand into the water's reflection to pull out a brass key.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The Sleeping Tax Collector finally wakes, too late.",
      "visual_description": "The Sleeping Tax Collector sits up, blinking at the empty square, papers stuck to his cheek as the others are far away.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The group races across the old stone bridge.",
      "visual_description": "Mara, the Glass Diver, the Oracle Lamp, and the Tin Fox sprint across a narrow bridge, its arches reflected in the dark water below.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The escape is complete as the bridge crumbles behind them.",
      "visual_description": "The four look back from the far side as the bridge collapses into the river, dust rising against a pale dawn sky.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    }
  ]
}

